head.script:
///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
    try {
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00310.onpageload" });
    }
};

scwin.onpageunload = function() {
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 *  화면 초기화
 */
scwin.init = function() {
    scwin.search();
};

/**
 *  데이터셋 초기화.
 */
scwin.initDs = function() {
    dlt_RelcomMutlTrdRes.removeAll();
};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {
    // 필수항목 체크.
    scwin.vKisCd     = $p.parent().wfm_header.getWindow().ibx_KisCd.getValue() ; 
    scwin.vAcntclsDt = $p.parent().wfm_header.getWindow().sbx_AcntclsDt.getValue();

    if (scwin.vKisCd === "" || scwin.vAcntclsDt === "") {
        return false;
    }
    return true;
};

/**
 * 관계회사상호거래  조회
 */
scwin.search = async function() {
  // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }

    let ibxKisCd = $p.parent().wfm_header.getWindow().ibx_KisCd.getValue() ; 
    let sbxAcntclsDt = $p.parent().wfm_header.getWindow().sbx_AcntclsDt.getValue();

    let url = "/api/listing/nice/individual-notes/other-corporate-investemnets?kisCd="+ibxKisCd+"&acntclsDt="+sbxAcntclsDt;
    await $c.sbm.setAction(sbm_dlt_RelcomMutlTrd, url);
    await $c.sbm.execute(sbm_dlt_RelcomMutlTrd);

    await scwin.appendContents(); 
};

/**
 * 컨텐츠 append
 */
scwin.appendContents = function() {
    let strContent = "<div style='overflow-x:hidden;overflow-y:scroll;width:100%;height:600px;font-family:돋움체;'>";
    for (let nRow = 0; nRow <= dlt_RelcomMutlTrdRes.getRowCount(); nRow++) {
        strContent = strContent + dlt_RelcomMutlTrdRes.getCellData(nRow, "ctnt");
    }
    strContent = strContent + "</div>";
    let grpCtntObj = $p.getComponentById("grp_Ctnt").render;
    grpCtntObj.innerHTML = strContent;
    grp_Ctnt.setStyle("border", "1px solid blue");
    grp_Ctnt.setStyle("magin-top", "30px");
};
